require __DIR__.'/../app/bootstrap.php';$u=require_seller();$title='My menu';$err=[];
if(post()){
 if(in_array(val('action'),['pause','resume'],true)){$status=val('action')==='pause'?'paused':'published';q('UPDATE menu_items SET status=?,updated_at=? WHERE id=? AND seller_id=? AND status=?',[$status,now(),(int)val('id'),$u['id'],val('action')==='pause'?'published':'paused']);flash('Availability updated.');go('seller/menu.php');}
 if(val('action')==='archive'){$id=(int)val('id');q("UPDATE menu_items SET status='archived',updated_at=? WHERE id=? AND seller_id=?",[now(),$id,$u['id']]);flash('Menu item archived. It is no longer visible to customers.');go('seller/menu.php');}
}
$items=all('SELECT m.*,c.name category_name,c.active category_active FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE m.seller_id=? ORDER BY m.id DESC',[$u['id']]);require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><h1>My menu</h1><p class="dash-sub">Every dish has its moment. Keep yours fresh.</p></div><a class="pill primary" href="<?=e(url('seller/menu-create.php'))?>">＋ Add menu item</a></div><section class="panel"><div class="panel-top"><h2>All dishes</h2><small><?=count($items)?> items</small></div><?php if(!$items): ?><p class="empty">Nothing on the menu yet. Add your first dish to get started.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Dish</th><th>Category</th><th>Price</th><th>Status</th><th>Expiry (<?=e(cfg('timezone'))?>)</th><th>Action</th></tr></thead><tbody><?php foreach($items as $m): $status=menu_state($m); ?><tr><td><img class="thumb" alt="" src="<?=e(image_url($m['photo_id']))?>"><?=e($m['name'])?></td><td><?=e($m['category_name'])?></td><td>Rs <?=number_format($m['price_paisa']/100,2)?></td><td><span class="chip <?=$status==='Live'?'':'pending'?>"><?=e($status)?></span></td><td><?php $w=window_for($m);$plan=schedule_for((int)$m['id']); ?><?=e($plan&&$plan['mode']==='weekly'?'Weekly · '.($w?local_time($w['start']->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s')):'Schedule ended'):local_time($m['expires_at']<'9999-01-01'?$m['expires_at']:null))?></td><td><div class="row-actions"><a class="pill compact" href="<?=e(url('seller/menu-edit.php?id='.$m['id']))?>">Edit</a><?php if($m['status']!=='archived'): ?><?php if(in_array($m['status'],['published','paused'],true)): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="<?=$m['status']==='paused'?'resume':'pause'?>"><button class="pill compact"><?=$m['status']==='paused'?'Resume':'Pause'?></button></form><?php endif ?><form method="post" data-confirm="Archive this dish? Customers will no longer see it."><?=csrf()?><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="archive"><button class="pill compact">Archive</button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
